const button=document.querySelector(".menu-toggle"),nav=document.querySelector("nav");button.addEventListener("click",()=>{const e=nav.classList.toggle("open");button.setAttribute("aria-expanded",String(e))}),document.querySelectorAll("nav a").forEach(e=>e.addEventListener("click",()=>{nav.classList.remove("open"),button.setAttribute("aria-expanded","false")}));const shareUrl=encodeURIComponent(location.href);document.querySelector(".share-facebook").href="https://www.facebook.com/sharer/sharer.php?u="+shareUrl,document.querySelector(".share-linkedin").href="https://www.linkedin.com/sharing/share-offsite/?url="+shareUrl,document.querySelector(".share-native").addEventListener("click",async()=>{navigator.share?await navigator.share({title:"Urban Coffee Novi Sad",url:location.href}):await navigator.clipboard.writeText(location.href)});